#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry complex. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam2022A3. Variable R : realType. Record point := Point { px : R; py : R }. Definition distance (P Q : point) : R := sqrt ((px P - px Q)^2 + (py P - py Q)^2). Definition circle (O : point) (r : R) := fun P : point => distance P O = r. Definition collinear (A B C : point) : Prop := ((px B - px A) * (py C - py A) = (py B - py A) * (px C - px A)). Definition area2 (A B C : point) : R := ((px B - px A) * (py C - py A) - (px C - px A) * (py B - py A)). Definition triangle_area (A B C : point) : R := `| area2 A B C | / 2. Variable O1 O2 : point. Let rP := 1. Let rQ := 4. Hypothesis H_tangent : distance O1 O2 = rP + rQ. Variables A B D : point. Hypothesis HAonP : circle O1 rP A. Hypothesis HBonQ : circle O2 rQ B. Hypothesis HADperp : True. Theorem external_tangent_triangle_area : exists area : R, area > 0. Proof. Admitted. End
